const rand=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.floor(Math.random()*a.length)];
let p=makePlayer(),map=createMap(),floor=1,wave=0,enemies=[],shots=[],effects=[],drops=[],hazards=[],path=[],target=null,roomKind='ruins';
