function drawDropItem(item,x,y){const color=rarities[item.rarity].color,rare=item.rarity>=2;ctx.save();ctx.translate(x,y-10);ctx.fillStyle='#02090baa';ctx.beginPath();ctx.ellipse(0,14,15,5,0,0,Math.PI*2);ctx.fill();ctx.translate(0,-5);ctx.shadowColor=color;ctx.shadowBlur=item.golden?18:rare?10:3;ctx.strokeStyle=color;ctx.fillStyle='#101a1d';ctx.lineWidth=item.golden?3:2;if(item.slot==='weapon'&&item.kind==='sword'){ctx.rotate(-.62);ctx.fillStyle='#d9e0dc';ctx.beginPath();ctx.moveTo(-2,-15);ctx.lineTo(3,-15);ctx.lineTo(4,10);ctx.lineTo(0,15);ctx.lineTo(-3,10);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#c79255';ctx.fillRect(-7,9,14,3);ctx.fillRect(-2,12,4,8);}else if(item.slot==='weapon'&&item.kind==='bow'){ctx.rotate(-.28);ctx.beginPath();ctx.moveTo(-8,-17);ctx.quadraticCurveTo(9,0,-8,17);ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='#dfd0a1';ctx.beginPath();ctx.moveTo(-8,-17);ctx.lineTo(-8,17);ctx.stroke();ctx.fillStyle=color;ctx.fillRect(-2,-2,13,3);}else if(item.slot==='weapon'&&item.kind==='staff'){ctx.beginPath();ctx.moveTo(0,-19);ctx.lineTo(0,17);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,-21,6,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#b98955';ctx.fillRect(-3,9,6,9);}else if(item.slot==='armor'){ctx.beginPath();ctx.moveTo(-12,-10);ctx.lineTo(-6,-16);ctx.lineTo(6,-16);ctx.lineTo(12,-10);ctx.lineTo(9,11);ctx.lineTo(0,17);ctx.lineTo(-9,11);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(0,-14);ctx.lineTo(0,13);ctx.stroke();}else{ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#101a1d';ctx.beginPath();ctx.arc(0,0,5,0,Math.PI*2);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,3,0,Math.PI*2);ctx.fill();}if(rare){ctx.shadowColor=color;ctx.shadowBlur=item.golden?15:7;ctx.strokeStyle=color;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-15,0);ctx.lineTo(-10,0);ctx.moveTo(10,0);ctx.lineTo(15,0);ctx.moveTo(0,-15);ctx.lineTo(0,-10);ctx.stroke();}ctx.restore();}
