  for(const [tx,ty] of [[3,3],[22,3],[3,14],[22,14]]){const x=tx*TILE+20,y=ty*TILE+10;const glow=ctx.createRadialGradient(x,y,2,x,y,105);glow.addColorStop(0,'#e6a46128');glow.addColorStop(1,'#d78b4500');ctx.fillStyle=glow;ctx.fillRect(x-105,y-105,210,210);ctx.fillStyle='#493b2c';ctx.fillRect(x-6,y,12,18);ctx.fillStyle='#ba8051';ctx.fillRect(x-7,y-4,14,5);ctx.fillStyle='#dcb16b';ctx.fillRect(x-4,y-11-Math.sin(t*8+tx)*2,8,10);ctx.fillStyle='#f8db94';ctx.fillRect(x-2,y-8,4,6);}
  if(path.length){ctx.strokeStyle='#8fceac4f';ctx.lineWidth=1;ctx.setLineDash([3,6]);ctx.beginPath();ctx.moveTo(p.x,p.y);for(const n of path)ctx.lineTo(n.x,n.y);ctx.stroke();ctx.setLineDash([]);const end=path[path.length-1];ctx.strokeStyle='#9dd3b7';ctx.beginPath();ctx.ellipse(end.x,end.y,10,5,0,0,Math.PI*2);ctx.stroke();}
  if(cleared){const gate=center(12,2);const glow=ctx.createRadialGradient(gate.x,gate.y,1,gate.x,gate.y,80);glow.addColorStop(0,'#66e9d94d');glow.addColorStop(1,'#66e9d900');ctx.fillStyle=glow;ctx.fillRect(gate.x-80,gate.y-80,160,160);ctx.save();ctx.translate(gate.x,gate.y);ctx.scale(1,.65);ctx.strokeStyle='#9febd5';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,26+Math.sin(t*3)*2,0,Math.PI*2);ctx.stroke();ctx.rotate(t);ctx.strokeRect(-19,-19,38,38);ctx.restore();label(wave===3?'进入下一层':'下一场战斗',gate.x,gate.y+45,'#9dddd1');const merchant=center(12,15);sprite('archer',merchant.x,merchant.y,3);label('烛火商会 [B]',merchant.x,merchant.y+28,'#dfbd83');}
  for(const h of hazards){const color=h.color||'#ed856a';ctx.fillStyle=color+'30';ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(h.x,h.y,h.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=color+'42';ctx.beginPath();ctx.arc(h.x,h.y,h.r*(1-h.life/h.max),0,Math.PI*2);ctx.fill();label(h.label||'闪避！',h.x,h.y,color,14);}
  for(const drop of drops){const color=rarities[drop.item.rarity].color;ctx.strokeStyle=color+'50';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(drop.x,drop.y);ctx.lineTo(drop.x,drop.y-35);ctx.stroke();drawDropItem(drop.item,drop.x,drop.y);if(distance(p,drop)<110)label(drop.item.name,drop.x,drop.y-42,color,11);}
  const bodies=[...enemies.filter(e=>e.hp>0),{...p,type:'hero',isPlayer:true}].sort((a,b)=>a.y-b.y);
  for(const e of bodies){if(e===target){ctx.strokeStyle='#ecc79c';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(e.x,e.y+12,e.r+6,9,0,0,Math.PI*2);ctx.stroke();}if(e.isPlayer){ctx.strokeStyle=p.invuln>0?'#d2eee2':'#77b7a37f';ctx.beginPath();ctx.ellipse(e.x,e.y+11,18,9,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=p.invuln>0?.6+Math.sin(t*40)*.25:1;}if(e.boss)drawBossForm(e,t);sprite(e.type,e.x,e.y,e.boss?6:e.type==='brute'?4:3,e.hit>0,e.elite);ctx.globalAlpha=1;if(!e.isPlayer&&!e.boss){ctx.fillStyle='#070f12';ctx.fillRect(e.x-16,e.y-32,32,3);ctx.fillStyle=e.elite?'#dbb878':'#b88476';ctx.fillRect(e.x-16,e.y-32,32*e.hp/e.maxHp,3);if(e.slow>0){ctx.strokeStyle='#97d9e3';ctx.strokeRect(e.x-17,e.y-22,34,36);}}if(e.isPlayer){ctx.save();ctx.translate(p.x+Math.cos(p.facing)*15,p.y+Math.sin(p.facing)*15);ctx.rotate(p.facing);ctx.fillStyle=weaponColor(p.equipment.weapon);ctx.shadowColor=weaponColor(p.equipment.weapon);ctx.shadowBlur=(p.equipment.weapon.rarity||0)*5;ctx.fillRect(0,-2,p.equipment.weapon.kind==='sword'?17:11,4);ctx.fillStyle='#bf9363';ctx.fillRect(-4,-4,5,8);ctx.restore();}}
  for(const s of shots){const color=s.color||(s.friendly?(s.magic?'#9cd9f6':'#d8bd82'):'#e6a16d'),rarity=s.rarity||0;ctx.save();ctx.strokeStyle=color;ctx.lineWidth=(s.magic?4:2)+Math.floor(rarity/2);ctx.shadowColor=color;ctx.shadowBlur=s.friendly?6+rarity*4:3;ctx.beginPath();ctx.moveTo(s.x-s.vx*(.025+rarity*.004),s.y-s.vy*(.025+rarity*.004));ctx.lineTo(s.x,s.y);ctx.stroke();if(s.friendly&&rarity>=2){ctx.strokeStyle=rarity>=4?'#fff4bd':'#ffffff';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(s.x-s.vx*.015+s.vy*.012,s.y-s.vy*.015-s.vx*.012);ctx.lineTo(s.x,s.y);ctx.stroke();}ctx.fillStyle=s.friendly?color:'#ffd3a0';ctx.beginPath();ctx.arc(s.x,s.y,(s.magic?3:2)+rarity*.7,0,Math.PI*2);ctx.fill();if(s.friendly&&rarity>=3){const spark=6+rarity*2;ctx.strokeStyle=rarity>=4?'#fff4bd':color;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(s.x-spark,s.y);ctx.lineTo(s.x+spark,s.y);ctx.moveTo(s.x,s.y-spark);ctx.lineTo(s.x,s.y+spark);ctx.stroke();}ctx.restore();}
  for(const e of effects){ctx.globalAlpha=clamp(e.life/e.max,0,1);if(e.type==='text')label(e.text,e.x,e.y,e.color,14);if(e.type==='particle'){ctx.save();ctx.fillStyle=e.color;if(e.glow){ctx.shadowColor=e.color;ctx.shadowBlur=10;}const s=e.size||3;ctx.fillRect(e.x-s/2,e.y-s/2,s,s);ctx.restore();}if(e.type==='ring'){ctx.save();ctx.strokeStyle=e.color;ctx.lineWidth=e.width||3;ctx.shadowColor=e.color;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(e.x,e.y,e.r*(1-e.life/e.max*.5),0,Math.PI*2);ctx.stroke();ctx.restore();}if(e.type==='rune'){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.angle+(1-e.life/e.max)*1.8);ctx.strokeStyle=e.color;ctx.lineWidth=2;ctx.shadowColor=e.color;ctx.shadowBlur=10;ctx.beginPath();for(let i=0;i<6;i++){const a=i*Math.PI/3;ctx.moveTo(Math.cos(a)*e.r*.72,Math.sin(a)*e.r*.72);ctx.lineTo(Math.cos(a)*e.r,Math.sin(a)*e.r);}ctx.stroke();ctx.beginPath();ctx.arc(0,0,e.r*(.7+.3*(1-e.life/e.max)),0,Math.PI*2);ctx.stroke();ctx.restore();}if(e.type==='slash'){ctx.save();ctx.strokeStyle=e.color||'#f4e1b1';ctx.lineWidth=e.rarity>=3?7:e.rarity>=1?6:5;ctx.shadowColor=e.color||'#f4e1b1';ctx.shadowBlur=e.rarity>=2?10:3;ctx.beginPath();ctx.arc(e.x,e.y,e.r*(.6+(1-e.life/e.max)*.4),e.angle-1.25,e.angle+1.25);ctx.stroke();ctx.restore();}if(e.type==='ghost'){sprite('hero',e.x,e.y,3);}}ctx.globalAlpha=1;
