  for(let i=0;i<25;i++){const x=(i*139+Math.sin(t*.3+i)*15)%1000+20,y=(i*83-t*(3+i%3))%680+20;ctx.globalAlpha=.15+Math.sin(t+i)*.12;ctx.fillStyle='#b2c798';ctx.fillRect(x,y,2,2);}ctx.globalAlpha=1;ctx.restore();if(screenFlash>0){ctx.save();ctx.globalAlpha=screenFlash;ctx.fillStyle=screenFlashColor;ctx.fillRect(0,0,1040,720);ctx.restore();}
