function frame(now){const dt=Math.min((now-last)/1000||0,.04);last=now;if(!paused&&running)update(dt);if(!paused){for(const e of effects){e.life-=dt;if(e.type==='text')e.y-=25*dt;if(e.type==='particle'){e.x+=e.vx*dt;e.y+=e.vy*dt;}}effects=effects.filter(e=>e.life>0);screenFlash=Math.max(0,screenFlash-dt*.8);toastTime-=dt;bannerTime-=dt;if(toastTime<=0)$('toast').classList.remove('show');if(bannerTime<=0)$('wave-banner').classList.remove('show');}draw(now/1000);uiClock+=dt;if(uiClock>.1){updateUI();uiClock=0;}requestAnimationFrame(frame);}
canvas.addEventListener('pointermove',event=>{const rect=canvas.getBoundingClientRect();aim={x:(event.clientX-rect.left)/rect.width*1040,y:(event.clientY-rect.top)/rect.height*720};});
canvas.addEventListener('pointerdown',event=>{if(!canAct())return;canvas.focus();const rect=canvas.getBoundingClientRect();aim={x:(event.clientX-rect.left)/rect.width*1040,y:(event.clientY-rect.top)/rect.height*720};if(event.button===2){held=true;attack();return;}if(event.button!==0)return;const selected=enemies.filter(e=>e.hp>0&&distance(e,aim)<e.r+15).sort((a,b)=>distance(a,aim)-distance(b,aim))[0];if(selected){target=selected;repath=0;$('mode').textContent='自动追击 · WASD 取消';}else if(cleared&&distance(aim,center(12,15))<35){showShop();}else{target=null;path=findPath(map,p,aim);$('mode').textContent='鼠标寻路 · WASD 接管';if(!path.length)toast('无法到达这里，请点击可通行的地面。');}});
canvas.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('pointerup',()=>held=false);
window.addEventListener('keydown',event=>{const key=event.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','tab'].includes(key)&&!modal.open)event.preventDefault();if(event.repeat)return;if(key==='escape'){event.preventDefault();pauseScreen();return;}if(modal.open)return;if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))keys.add(key);if(key==='shift')skill('dash');if(key==='1')skill('spin');if(key==='2')skill('frost');if(key==='q')potion();if(key==='i'&&running)showInventory();if(key==='b'&&running)showShop();if(key==='e')interact();if(key==='?')showHelp();});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();held=false;if(running&&!paused)pauseScreen();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused)pauseScreen();});
modal.addEventListener('cancel',e=>{e.preventDefault();if(['pause','help','inventory','shop','confirm'].includes(currentModal)&&running)closeModal();});
$('modal-content').addEventListener('click',event=>{const button=event.target.closest?.('button');if(button?.dataset.action!=='buy-potion')return;event.preventDefault?.();event.stopImmediatePropagation?.();if(p.gold<59){toast('购买生命药水需要 59 金。');return;}if(p.potions>=9){toast('生命药水已达持有上限。');return;}p.gold-=59;p.potions++;log('购入生命药水。');tone(720,.12);showShop('forge');updateUI();},true);
$('modal-content').addEventListener('click',event=>{const button=event.target.closest?.('button');if(button?.dataset.action!=='heal')return;event.preventDefault?.();event.stopImmediatePropagation?.();const cost=70+floor*25;if(p.gold<cost){toast(`营火治疗需要 ${cost} 金。`);return;}if(p.hp>=p.maxHp){toast('生命已满。');return;}p.gold-=cost;p.hp=p.maxHp;log(`支付 ${cost} 金，营火恢复了全部生命。`);tone(510,.18);showShop('forge');updateUI();},true);
$('modal-content').addEventListener('click',event=>{const button=event.target.closest?.('button');if(!button||button.disabled)return;const capture=event.eventPhase===1;if(capture&&!button.dataset.talent)return;if(button.dataset.talent){applyTalent(button.dataset.talent);log(`获得天赋：${button.querySelector('strong').textContent}`);closeModal();updateUI();event.stopImmediatePropagation?.();return;}if(button.dataset.elixir){buyElixir(button.dataset.elixir);return;}if(capture)event.stopImmediatePropagation?.();if(button.dataset.weapon){chosen=button.dataset.weapon;startScreen();return;}if(button.dataset.shop){showShop(button.dataset.shop);return;}if(button.dataset.equip!==undefined){equip(+button.dataset.equip);return;}if(button.dataset.buy!==undefined){const i=+button.dataset.buy,item=stock[i];if(item&&p.gold>=price(item)&&p.inventory.length<40){p.gold-=price(item);p.inventory.push(item);stock[i]=null;log(`购入${item.name}。`);tone(630);showShop();updateUI();}else if(p.inventory.length>=40)toast('背包已满，请先出售装备。');return;}if(button.dataset.sell!==undefined){const index=+button.dataset.sell,item=p.inventory[index];if(item){p.gold+=price(item,true);p.inventory.splice(index,1);tone(550);showShop('sell');updateUI();}return;}const action=button.dataset.action;if(action==='start')start();if(action==='restart')startScreen();if(action==='close')closeModal();if(action==='help')showHelp();if(action==='confirm-restart')openModal('confirm','<h2 class="modal-title">重新出发？</h2><p class="modal-subtitle">本次远征的装备、金币和天赋会重置。</p><div class="modal-actions"><button data-action="close">继续当前远征</button><button class="primary" data-action="restart">重新选择武器</button></div>');if(action==='leave-shop'){closeModal();proceed();}if(action==='refresh'&&p.gold>=15+refreshCount*10){p.gold-=15+refreshCount*10;refreshCount++;generateStock();showShop();}if(action==='forge'){const w=p.equipment.weapon,cost=45+(w.enhance||0)*35;if(p.gold>=cost&&(w.enhance||0)<5){p.gold-=cost;w.enhance=(w.enhance||0)+1;w.attack+=5;log(`${w.name}强化至 +${w.enhance}。`);tone(280,.2);showShop('forge');}}if(action==='buy-potion'&&p.gold>=22&&p.potions<9){p.gold-=22;p.potions++;showShop('forge');}if(action==='heal'&&p.gold>=18&&p.hp<p.maxHp){p.gold-=18;p.hp=p.maxHp;showShop('forge');}if(action==='vitality'&&p.gold>=65){p.gold-=65;p.maxHp+=20;p.hp+=20;}updateUI();},true);
$('modal-content').addEventListener('change',e=>{if(e.target.id==='elite-choice')eliteNext=e.target.checked;});
$('modal-content').addEventListener('click',event=>{const button=event.target.closest('button');if(!button||button.disabled)return;if(button.dataset.weapon){chosen=button.dataset.weapon;startScreen();return;}if(button.dataset.shop){showShop(button.dataset.shop);return;}if(button.dataset.equip!==undefined){equip(+button.dataset.equip);return;}if(button.dataset.buy!==undefined){const i=+button.dataset.buy,item=stock[i];if(item&&p.gold>=price(item)&&p.inventory.length<40){p.gold-=price(item);p.inventory.push(item);stock[i]=null;log(`购入${item.name}。`);tone(630);showShop();updateUI();}else if(p.inventory.length>=40){toast('背包已满，请先出售装备。');}return;}if(button.dataset.sell!==undefined){const index=+button.dataset.sell,item=p.inventory[index];if(item){p.gold+=price(item,true);p.inventory.splice(index,1);tone(550);showShop('sell');updateUI();}return;}if(button.dataset.talent){const id=button.dataset.talent;if(id==='power')p.bonusAttack+=5;if(id==='vigor'){p.maxHp+=25;p.hp=Math.min(p.maxHp,p.hp+25);}if(id==='crit')p.bonusCrit=(p.bonusCrit||0)+6;if(id==='leech')p.bonusLeech=(p.bonusLeech||0)+4;if(id==='armor')p.bonusArmor=(p.bonusArmor||0)+3;if(id==='haste')p.bonusSpeed=(p.bonusSpeed||0)+.08;log(`获得天赋：${button.querySelector('strong').textContent}`);closeModal();updateUI();return;}const action=button.dataset.action;if(action==='start')start();if(action==='restart')startScreen();if(action==='close')closeModal();if(action==='help')showHelp();if(action==='confirm-restart')openModal('confirm','<h2 class="modal-title">重新出发？</h2><p class="modal-subtitle">本次远征的装备、金币和天赋会重置。</p><div class="modal-actions"><button data-action="close">继续当前远征</button><button class="primary" data-action="restart">重新选择武器</button></div>');if(action==='leave-shop'){closeModal();proceed();}if(action==='refresh'&&p.gold>=15+refreshCount*10){p.gold-=15+refreshCount*10;refreshCount++;generateStock();showShop();}if(action==='forge'){const w=p.equipment.weapon,cost=45+(w.enhance||0)*35;if(p.gold>=cost&&(w.enhance||0)<5){p.gold-=cost;w.enhance=(w.enhance||0)+1;w.attack+=5;log(`${w.name}强化至 +${w.enhance}。`);tone(280,.2);showShop('forge');}}if(action==='buy-potion'&&p.gold>=22&&p.potions<9){p.gold-=22;p.potions++;showShop('forge');}if(action==='heal'&&p.gold>=18&&p.hp<p.maxHp){p.gold-=18;p.hp=p.maxHp;showShop('forge');}if(action==='vitality'&&p.gold>=65){p.gold-=65;p.maxHp+=20;p.hp+=20;showShop('forge');}updateUI();});
$('pause').onclick=pauseScreen;$('help').onclick=showHelp;$('inventory').onclick=()=>running&&showInventory();$('sound').onclick=()=>{soundEnabled=!soundEnabled;$('sound').textContent=`音效：${soundEnabled?'开':'关'}`;$('sound').setAttribute('aria-pressed',String(soundEnabled));tone(500);};$('basic').onclick=attack;$('dash').onclick=()=>skill('dash');$('spin').onclick=()=>skill('spin');$('frost').onclick=()=>skill('frost');$('potion').onclick=potion;$('interact').onclick=interact;
